{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Saccharin, a low-molecular-weight imide-like molecule with a very high assay-transfer score, showed absolute oral bioavailability of 0.85±0.04 in fed humans, supporting high F for the query's imide/lactam-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Bromazepam, a fused heterocyclic lactam/benzodiazepine with a very high transfer score, had an absolute bioavailability of 86% in humans, supporting high oral bioavailability for the fused bicyclic lactam query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Lamivudine, a polar low-MW drug with a very high transfer score, showed absolute bioavailability of 69±9% in fasted patients, demonstrating that low logP and moderate polarity do not preclude F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Rolipram, a lactam-containing drug with a very high transfer score, was completely absorbed with 73% bioavailability in healthy volunteers, supporting high F for the lactam-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Navoximod, a fused heterocyclic compound with a very high transfer score, had an absolute bioavailability of 55.5% after oral dosing, still well above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Oxcarbazepine, a fused aromatic lactam/imide-like antiepileptic with a very high transfer score, showed approximately 95% oral bioavailability, supporting high F for the query's fused aromatic lactam system.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability well above 20% (55–99%), and the query's low molecular weight, neutral character, and moderate polarity are consistent with good absorption. No affirmative evidence supports F<20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule.",
    "No analogue exactly matches the primary aromatic amine plus glutarimide substitution pattern, so aniline-related first-pass metabolism is inferred rather than directly measured.",
    "Most analogues are neutral or nucleoside-like; none directly probes the query's specific transporter or metabolic liabilities."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

